# 读取现有数据
with open('data/data.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# 为每个单词添加词根解释
added_count = 0
for root in data['roots']:
    root_name = root['name']
    
    # 提取词根前缀（如 "co- (共同,一起)" -> "co-"）
    root_prefix = root_name.split(' ')[0] if ' ' in root_name else root_name
    
    for word_obj in root['words']:
        word = word_obj['word'].lower()
        
        # 如果已经有词根解释，跳过
        if 'etymology' in word_obj:
            continue
        
        # 先查找特定单词的词根分解
        if word in specific_etymologies:
            word_obj['etymology'] = specific_etymologies[word]
            added_count += 1
        else:
            # 尝试根据词根前缀生成解释
            if root_prefix.endswith('-') and root_prefix in root_components:
                prefix_meaning = root_components[root_prefix]
                # 生成简单的解释
                word_obj['etymology'] = f'{root_prefix}({prefix_meaning}) + 词根 → {word_obj.get("meaning", "")}'
                added_count += 1
            else:
                # 对于没有明确前缀的词根，添加通用解释
                word_obj['etymology'] = f'属于{root_name}词根家族 → {word_obj.get("meaning", "")}'
                added_count += 1

# 保存更新后的数据
with open('data/data.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

print(f'已为 {added_count} 个单词添加词根解释')

